102	  const showMetricName = chartProps.rawFormData?.show_metric_name ?? false;
103	  const compareLag = Number(compareLag_) || 0;
104	  let formattedSubheader = subheader;
105	
106	  const { r, g, b } = colorPicker;
107	  const mainColor = `rgb(${r}, ${g}, ${b})`;
108	
109	  const xAxisLabel = getXAxisLabel(rawFormData) as string;
110	  let trendLineData: TimeSeriesDatum[] | undefined;
111	  let percentChange = 0;
112	  let bigNumber = data.length === 0 ? null : data[0][metricName];
113	  let timestamp = data.length === 0 ? null : data[0][xAxisLabel];
114	  let bigNumberFallback = null;
115	  let sortedData: [number | null, number | null][] = [];
116	
117	  if (data.length > 0) {
118	    sortedData = (data as BigNumberDatum[])
