128	  }
129	  if (hasAggregatedData && aggregatedData) {
130	    if (
131	      aggregatedData[metricName] !== null &&
132	      aggregatedData[metricName] !== undefined
133	    ) {
134	      bigNumber = aggregatedData[metricName];
135	    } else {
136	      const metricKeys = Object.keys(aggregatedData).filter(
137	        key =>
138	          key !== xAxisLabel &&
139	          aggregatedData[key] !== null &&
140	          typeof aggregatedData[key] === 'number',
141	      );
142	      bigNumber = metricKeys.length > 0 ? aggregatedData[metricKeys[0]] : null;
143	    }
144	
145	    timestamp = sortedData.length > 0 ? sortedData[0][0] : null;
146	  } else if (sortedData.length > 0) {
147	    bigNumber = sortedData[0][1];
148	    timestamp = sortedData[0][0];
149	
150	    if (bigNumber === null) {
151	      bigNumberFallback = sortedData.find(d => d[1] !== null);
152	      bigNumber = bigNumberFallback ? bigNumberFallback[1] : null;
153	      timestamp = bigNumberFallback ? bigNumberFallback[0] : null;
154	    }
155	  }
156	
157	  if (compareLag > 0 && sortedData.length > 0) {
