61	    const queryContext = buildQuery({ ...baseFormData, aggregation: 'sum' });
62	    const bigNumberQuery = queryContext.queries[1];
63	
64	    expect(bigNumberQuery.post_processing).toEqual([
65	      { operation: 'pivot' },
66	      { operation: 'aggregation', options: { operator: 'sum' } },
67	    ]);
68	    expect(bigNumberQuery.is_timeseries).toBe(true);
69	  });
